// Build: pre-renders every page in IT / DE / EN from src/pages/*.html.
//
//   node scripts/build.mjs
//
// Output (committed, served as-is by GitHub Pages from the repository root):
//   index.html (language redirect), it/, de/, en/, 404.html, sitemap.xml, robots.txt, sw.js, .nojekyll
//
// Template syntax:
//   {{key}}          translated text, HTML-escaped (build fails on a missing key)
//   {{$var}}         HTML generated by this script
//   {{>partial}}     src/partials/partial.html
//   <!--if:flag-->…<!--/if:flag-->   kept only when the flag is true

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import { hut, site, features, reservations } from "../src/data/hut.config.js";
import { menu, categories, diets } from "../src/data/menu.js";
import { gallery } from "../src/data/gallery.js";
import { trail } from "../src/data/trail.js";
import { ega } from "../src/features/ega-scotoni/data.js";
import { renderEgaPage, renderEgaTeaser, egaMeta, egaNavLabel } from "../src/features/ega-scotoni/ega-scotoni.js";
import { artSVG } from "../src/js/art.js";
import it from "../src/i18n/it.js";
import de from "../src/i18n/de.js";
import en from "../src/i18n/en.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LANGS = site.languages;
const DICTS = { it, de, en };
const LOCALE = { it: "it-IT", de: "de-DE", en: "en-GB" };
const LANG_NAME = { it: "Italiano", de: "Deutsch", en: "English" };
const BASE = site.baseUrl.endsWith("/") ? site.baseUrl : site.baseUrl + "/";

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const read = (p) => readFileSync(join(ROOT, p), "utf8");
const num = (lang, n) => new Intl.NumberFormat(LOCALE[lang]).format(n);

function buildVars(lang) {
  const address = [hut.address.street, [hut.address.postalCode, hut.address.locality].filter(Boolean).join(" "), hut.address.region].join(", ");
  return {
    altitude: num(lang, hut.altitudeM),
    family: hut.family,
    years: hut.familyYears,
    beds: hut.beds,
    wines: num(lang, hut.wineLabels),
    email: hut.email,
    address,
    startAlt: num(lang, trail.start.altitudeM),
    lakeAlt: num(lang, trail.extension.altitudeM),
    year: new Date().getFullYear(),
  };
}

function interp(str, vars) {
  return str.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
}

function dictFor(lang) {
  return { ...DICTS[lang], "ega.nav": egaNavLabel(lang) };
}

function t(lang, key) {
  const d = dictFor(lang);
  if (!(key in d)) throw new Error(`Missing translation "${key}" for ${lang}`);
  return interp(d[key], buildVars(lang));
}

const mapsUrl = (q) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
const mapsDir = (lat, lon) => `https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}&travelmode=walking`;

function flags() {
  return {
    ...features,
    hasPhone: Boolean(hut.phone),
    hasReviews: Boolean(hut.links.reviews),
    altitudeUnverified: !hut.altitudeVerified,
    reservationDemo: reservations.demo,
    galleryPlaceholders: gallery.some((g) => !g.photo),
  };
}

// ------------------------------------------------------------------ components

function langSwitcher(lang, file) {
  const items = LANGS.map((l) => `<li><a href="../${l}/${file}" hreflang="${l}" lang="${l}" data-set-lang="${l}" aria-label="${LANG_NAME[l]}"${l === lang ? ' aria-current="true"' : ""}>${l.toUpperCase()}</a></li>`).join("");
  return `<ul class="lang-switch" aria-label="${esc(t(lang, "nav.lang"))}">${items}</ul>`;
}

function formatPrice(lang, value) {
  return new Intl.NumberFormat(LOCALE[lang], { style: "currency", currency: "EUR" }).format(value);
}

function menuFilters(lang) {
  const chip = (type, name, value, label, checked) =>
    `<label class="chip"><input type="${type}" name="${name}" value="${value}"${checked ? " checked" : ""}><span>${esc(label)}</span></label>`;
  return `<div class="filters" data-menu-filters hidden>
        <fieldset class="chips"><legend>${esc(t(lang, "food.filter_course"))}</legend>${chip("radio", "cat", "", t(lang, "food.all"), true)}${categories.map((c) => chip("radio", "cat", c, t(lang, `cat.${c}`))).join("")}</fieldset>
        <fieldset class="chips"><legend>${esc(t(lang, "food.filter_diet"))}</legend>${diets.map((d) => chip("checkbox", "diet", d, t(lang, `diet.${d}`))).join("")}</fieldset>
      </div>`;
}

function menuItems(lang) {
  return menu.map((m) => {
    const price = hut.prices?.[m.id];
    const name = m.link ? `<a href="${m.link}">${esc(m.name[lang])}</a>` : esc(m.name[lang]);
    const tags = m.tags.map((tag) => `<li class="tag tag-${tag}">${esc(t(lang, `diet.${tag}`))}</li>`).join("");
    return `<li class="menu-item${m.signature ? " is-signature" : ""}" data-cat="${m.cat}" data-tags="${m.tags.join(" ")}">
          <div class="menu-item-head"><h3>${name}</h3>${price != null ? `<span class="price">${esc(formatPrice(lang, price))}</span>` : ""}</div>
          ${m.signature ? `<p class="signature">★ ${esc(t(lang, "food.signature"))}</p>` : ""}
          <p>${esc(m.desc[lang])}</p>
          <p class="menu-cat">${esc(t(lang, `cat.${m.cat}`))}</p>
          ${tags ? `<ul class="tags">${tags}</ul>` : ""}
        </li>`;
  }).join("\n        ");
}

/** Schematic elevation profile, x = walking time. Drawn at build time so it works without JS. */
function trailProfile(lang) {
  const W = 640, H = 270, padL = 56, padR = 24, padT = 30, padB = 44;
  const totalMin = trail.minutes + trail.extension.minutes;
  const minAlt = Math.floor((trail.start.altitudeM - 80) / 100) * 100;
  const maxAlt = Math.ceil((trail.extension.altitudeM + 60) / 100) * 100;
  const x = (min) => padL + (min / totalMin) * (W - padL - padR);
  const y = (alt) => padT + (1 - (alt - minAlt) / (maxAlt - minAlt)) * (H - padT - padB);
  const climb = hut.altitudeM - trail.start.altitudeM;
  const main = trail.shape.map(([ft, fa]) => [ft * trail.minutes, trail.start.altitudeM + fa * climb]);
  const ext = [[trail.minutes, hut.altitudeM], [trail.minutes + 12, hut.altitudeM + (trail.extension.altitudeM - hut.altitudeM) * 0.45], [totalMin, trail.extension.altitudeM]];
  const line = (pts) => pts.map(([m, a], i) => `${i ? "L" : "M"}${x(m).toFixed(1)} ${y(a).toFixed(1)}`).join(" ");
  const area = (pts) => `${line(pts)} L${x(pts.at(-1)[0]).toFixed(1)} ${y(minAlt).toFixed(1)} L${x(pts[0][0]).toFixed(1)} ${y(minAlt).toFixed(1)}Z`;
  const gridAlts = [];
  for (let a = minAlt; a <= maxAlt; a += 100) gridAlts.push(a);
  const grid = gridAlts.map((a) => `<line x1="${padL}" x2="${W - padR}" y1="${y(a).toFixed(1)}" y2="${y(a).toFixed(1)}"/><text x="${padL - 8}" y="${(y(a) + 5).toFixed(1)}" text-anchor="end">${num(lang, a)}</text>`).join("");
  const ticks = [0, 15, 30, 45, 60, 75, 90].map((m) => `<text x="${x(m).toFixed(1)}" y="${H - 14}" text-anchor="middle"${m > trail.minutes ? ' class="ext"' : ""}>${esc(interp(t(lang, "trail.minutes"), { n: m }))}</text>`).join("");
  const point = (m, a, label, cls = "") => `<g class="pt ${cls}"><circle cx="${x(m).toFixed(1)}" cy="${y(a).toFixed(1)}" r="5"/><text x="${x(m).toFixed(1)}" y="${(y(a) - 12).toFixed(1)}" text-anchor="${m === 0 ? "start" : m >= totalMin ? "end" : "middle"}">${esc(label)} · ${num(lang, a)} m</text></g>`;
  return `<svg class="profile-svg" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="profile-title profile-desc">
            <title id="profile-title">${esc(t(lang, "trail.profile_title"))}</title>
            <desc id="profile-desc">${esc(t(lang, "trail.profile_desc"))}</desc>
            <g class="grid">${grid}</g>
            <g class="ticks">${ticks}</g>
            <path class="area" d="${area(main)}"/>
            <path class="line" d="${line(main)}"/>
            <g class="extension" data-extension-layer>
              <path class="area" d="${area(ext)}"/>
              <path class="line" d="${line(ext)}"/>
              ${point(totalMin, trail.extension.altitudeM, t(lang, "trail.point_lake"), "ext")}
            </g>
            ${point(0, trail.start.altitudeM, t(lang, "trail.point_start"))}
            ${point(trail.minutes, hut.altitudeM, t(lang, "trail.point_hut"), "hut")}
          </svg>`;
}

function alpacaCards(lang) {
  return [1, 2, 3, 4, 5].map((n) => `<li class="alpaca">
          <button type="button" class="alpaca-front" aria-expanded="false" aria-controls="alpaca-fact-${n}">
            ${artSVG("alpaca")}
            <span class="alpaca-title">${esc(interp(t(lang, "family.card"), { n }))}</span>
            <span class="alpaca-hint" aria-hidden="true">${esc(t(lang, "family.flip"))}</span>
          </button>
          <p class="alpaca-fact" id="alpaca-fact-${n}" hidden>${esc(t(lang, `family.fact${n}`))}</p>
        </li>`).join("\n        ");
}

function picture(photo, alt, sizes) {
  const set = (ext) => [480, 960, 1600].map((w) => `../assets/photos/${photo.file}-${w}.${ext} ${w}w`).join(", ");
  return `<picture><source type="image/avif" srcset="${set("avif")}" sizes="${sizes}"><source type="image/webp" srcset="${set("webp")}" sizes="${sizes}"><img src="../assets/photos/${photo.file}-960.jpg" srcset="${set("jpg")}" sizes="${sizes}" width="${photo.width}" height="${photo.height}" alt="${esc(alt)}" loading="lazy" decoding="async"></picture>`;
}

function galleryGrid(lang) {
  return gallery.map((g, i) => {
    const media = g.photo ? picture(g.photo, "", "(min-width: 900px) 33vw, 50vw") : artSVG(g.art);
    return `<li><button type="button" class="gallery-item" data-index="${i}" data-caption="${esc(g.caption[lang])}" data-alt="${esc(g.alt[lang])}" aria-label="${esc(interp(t(lang, "gallery.open"), { caption: g.caption[lang] }))}">
          ${media}
          <span class="gallery-caption">${esc(g.caption[lang])}</span>
        </button></li>`;
  }).join("\n        ");
}

function jsonLd(lang, url) {
  const data = {
    "@context": "https://schema.org",
    "@type": ["Restaurant", "LodgingBusiness"],
    name: hut.name,
    url,
    description: t(lang, "meta.index.description"),
    inLanguage: lang,
    email: hut.email,
    ...(hut.phone ? { telephone: hut.phone } : {}),
    address: {
      "@type": "PostalAddress",
      streetAddress: hut.address.street,
      addressLocality: hut.address.locality,
      addressRegion: hut.address.region,
      ...(hut.address.postalCode ? { postalCode: hut.address.postalCode } : {}),
      addressCountry: hut.address.country,
    },
    geo: { "@type": "GeoCoordinates", latitude: hut.geo.lat, longitude: hut.geo.lon, elevation: hut.altitudeM },
    servesCuisine: ["South Tyrolean", "Alpine", "Barbecue"],
    acceptsReservations: features.onlineBooking,
    containedInPlace: { "@type": "Park", name: hut.park },
    amenityFeature: [
      { "@type": "LocationFeatureSpecification", name: "Children's playground", value: true },
      { "@type": "LocationFeatureSpecification", name: "Alpaca park", value: true },
    ],
    ...(hut.openingHours ? { openingHoursSpecification: openingSpec() } : {}),
    ...(hut.links.instagram ? { sameAs: [hut.links.instagram] } : {}),
  };
  return `<script type="application/ld+json">${JSON.stringify(data).replace(/</g, "\\u003c")}</script>`;
}

function openingSpec() {
  const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const seasons = hut.seasons?.length ? hut.seasons : [null];
  return Object.entries(hut.openingHours).flatMap(([d, [opens, closes]]) => seasons.map((s) => ({
    "@type": "OpeningHoursSpecification",
    dayOfWeek: `https://schema.org/${days[d]}`,
    opens, closes,
    ...(s ? { validFrom: `--${s.from}`, validThrough: `--${s.to}` } : {}),
  })));
}

// ------------------------------------------------------------------ templating

function render(template, lang, vars) {
  let out = template.replace(/\{\{>(\w+)\}\}/g, (m, name) => read(`src/partials/${name}.html`));
  const f = flags();
  // Innermost first so conditionals can nest.
  let prev;
  do {
    prev = out;
    out = out.replace(/<!--if:(\w+)-->((?:(?!<!--if:)[\s\S])*?)<!--\/if:\1-->/g, (m, flag, body) => {
      if (!(flag in f)) throw new Error(`Unknown flag "${flag}"`);
      return f[flag] ? body : "";
    });
  } while (out !== prev);
  out = out.replace(/\{\{\$(\w+)\}\}/g, (m, k) => {
    if (!(k in vars)) throw new Error(`Missing build var "${k}"`);
    return vars[k];
  });
  out = out.replace(/\{\{([\w.]+)\}\}/g, (m, key) => esc(t(lang, key)));
  return out;
}

function pageUrl(lang, file) {
  return `${BASE}${lang}/${file === "index.html" ? "" : file}`;
}

function documentShell({ lang, file, key, body, noindex, styles = [], extraHead = "", title, description }) {
  const canonical = pageUrl(lang, file);
  const alternates = LANGS.map((l) => `<link rel="alternate" hreflang="${l}" href="${pageUrl(l, file)}">`).join("\n  ");
  const ogAlt = LANGS.filter((l) => l !== lang).map((l) => `<meta property="og:locale:alternate" content="${t(l, "meta.locale")}">`).join("\n  ");
  const css = ["../src/styles/main.css", ...styles].map((href) => `<link rel="stylesheet" href="${href}">`).join("\n  ");
  return `<!doctype html>
<html lang="${lang}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)}</title>
  <meta name="description" content="${esc(description)}">
  ${noindex ? '<meta name="robots" content="noindex, nofollow">' : `<link rel="canonical" href="${canonical}">
  ${alternates}
  <link rel="alternate" hreflang="x-default" href="${BASE}">`}
  <meta property="og:type" content="website">
  <meta property="og:site_name" content="${esc(hut.name)}">
  <meta property="og:title" content="${esc(title)}">
  <meta property="og:description" content="${esc(description)}">
  <meta property="og:url" content="${canonical}">
  <meta property="og:locale" content="${t(lang, "meta.locale")}">
  ${ogAlt}
  <meta name="twitter:card" content="summary">
  <meta name="theme-color" content="#f6f1e7" media="(prefers-color-scheme: light)">
  <meta name="theme-color" content="#151a2b" media="(prefers-color-scheme: dark)">
  <meta name="color-scheme" content="light dark">
  <link rel="icon" href="../assets/icon.svg" type="image/svg+xml">
  <script>try{var t=localStorage.getItem("scotoni-theme");if(t==="day"||t==="night")document.documentElement.dataset.theme=t==="day"?"light":"dark"}catch(e){}</script>
  ${css}
  <script type="module" src="../src/js/site.js"></script>
  ${extraHead}
</head>
<body data-page="${key}">
${body}
</body>
</html>
`;
}

function parsePage(src) {
  const m = src.match(/^<!--page (\{[\s\S]*?\}) -->\n/);
  if (!m) throw new Error("Page template must start with <!--page {...} -->");
  return { meta: JSON.parse(m[1]), body: src.slice(m[0].length) };
}

// ------------------------------------------------------------------ build

function clean() {
  for (const l of LANGS) rmSync(join(ROOT, l), { recursive: true, force: true });
  for (const f of ["index.html", "404.html", "sitemap.xml", "robots.txt", "sw.js"]) rmSync(join(ROOT, f), { force: true });
}

function write(path, content) {
  const full = join(ROOT, path);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content);
}

function listFiles(dir) {
  const out = [];
  for (const name of readdirSync(join(ROOT, dir))) {
    const p = join(dir, name);
    if (statSync(join(ROOT, p)).isDirectory()) out.push(...listFiles(p));
    else out.push(p);
  }
  return out;
}

export function build() {
  clean();
  const pages = readdirSync(join(ROOT, "src/pages")).filter((f) => f.endsWith(".html"));
  const built = [];

  for (const lang of LANGS) {
    for (const file of pages) {
      const { meta, body } = parsePage(read(`src/pages/${file}`));
      if (meta.feature && !features[meta.feature]) continue;
      const vars = {
        langSwitcher: langSwitcher(lang, file),
        address: esc(buildVars(lang).address),
        email: esc(hut.email),
        phone: esc(hut.phone || ""),
        phoneHref: esc((hut.phone || "").replace(/[^\d+]/g, "")),
        mapsHut: esc(mapsDir(hut.geo.lat, hut.geo.lon)),
        mapsStart: esc(mapsUrl(trail.start.mapsQuery)),
        reviewsUrl: esc(hut.links.reviews || ""),
        menuFilters: menuFilters(lang),
        menuItems: menuItems(lang),
        trailProfile: trailProfile(lang),
        alpacaCards: alpacaCards(lang),
        galleryGrid: galleryGrid(lang),
        egaTeaser: features.egaScotoni ? renderEgaTeaser(lang) : "",
      };
      const styles = (meta.styles || []).map((s) => `../src/styles/${s}`);
      if (meta.key === "index" && features.egaScotoni) styles.push("../src/features/ega-scotoni/ega-scotoni.css");
      const url = pageUrl(lang, file);
      const html = documentShell({
        lang, file, key: meta.key, noindex: meta.noindex, styles,
        title: t(lang, `meta.${meta.key}.title`), description: t(lang, `meta.${meta.key}.description`),
        body: render(body, lang, vars),
        extraHead: meta.jsonld ? jsonLd(lang, url) : "",
      });
      write(`${lang}/${file}`, html);
      built.push({ lang, file, noindex: meta.noindex });
    }

    if (features.egaScotoni) {
      const file = `${ega.slug}.html`;
      const shell = `{{>header}}\n${renderEgaPage(lang)}\n{{>footer}}`;
      const m = egaMeta(lang);
      write(`${lang}/${file}`, documentShell({
        lang, file, key: "ega", title: m.title, description: m.description,
        styles: ["../src/features/ega-scotoni/ega-scotoni.css"],
        body: render(shell, lang, { langSwitcher: langSwitcher(lang, file), address: esc(buildVars(lang).address), email: esc(hut.email), phone: esc(hut.phone || ""), phoneHref: esc((hut.phone || "").replace(/[^\d+]/g, "")) }),
      }));
      built.push({ lang, file });
    }
  }

  // Root: send visitors to their saved or browser language.
  const langList = JSON.stringify(LANGS);
  write("index.html", `<!doctype html>
<html lang="${site.defaultLanguage}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Rifugio Scotoni</title>
  <meta name="description" content="${esc(t(site.defaultLanguage, "meta.index.description"))}">
  <link rel="canonical" href="${pageUrl(site.defaultLanguage, "index.html")}">
  ${LANGS.map((l) => `<link rel="alternate" hreflang="${l}" href="${pageUrl(l, "index.html")}">`).join("\n  ")}
  <link rel="alternate" hreflang="x-default" href="${BASE}">
  <script>
    (function () {
      var langs = ${langList}, pick = null;
      try { pick = localStorage.getItem("scotoni-lang"); } catch (e) {}
      if (langs.indexOf(pick) < 0) {
        pick = null;
        var prefs = navigator.languages || [navigator.language || ""];
        for (var i = 0; i < prefs.length && !pick; i++) {
          var code = String(prefs[i]).slice(0, 2).toLowerCase();
          if (langs.indexOf(code) >= 0) pick = code;
        }
      }
      location.replace((pick || "${site.defaultLanguage}") + "/" + location.search + location.hash);
    })();
  </script>
  <noscript><meta http-equiv="refresh" content="0; url=${site.defaultLanguage}/"></noscript>
</head>
<body>
  <p>Rifugio Scotoni: ${LANGS.map((l) => `<a href="${l}/" hreflang="${l}" lang="${l}">${LANG_NAME[l]}</a>`).join(" · ")}</p>
</body>
</html>
`);

  write("404.html", `<!doctype html>
<html lang="${site.defaultLanguage}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">
<title>${esc(t(site.defaultLanguage, "meta.404.title"))}</title>
<style>body{font:1.1rem/1.6 system-ui,sans-serif;max-width:36rem;margin:15vh auto;padding:0 16px;color:#2a2420;background:#f6f1e7}a{color:#8f3b1f}@media (prefers-color-scheme:dark){body{background:#151a2b;color:#ece6dc}a{color:#f0a27e}}</style></head>
<body><main><h1>Rifugio Scotoni</h1>
${LANGS.map((l) => `<p lang="${l}">${esc(t(l, "meta.404.description"))} <a href="${BASE}${l}/">${LANG_NAME[l]} →</a></p>`).join("\n")}
</main></body></html>
`);

  const indexable = built.filter((b) => !b.noindex);
  const files = [...new Set(indexable.map((b) => b.file))];
  write("sitemap.xml", `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">
${files.flatMap((file) => LANGS.filter((l) => indexable.some((b) => b.lang === l && b.file === file)).map((l) => `  <url>
    <loc>${pageUrl(l, file)}</loc>
${LANGS.map((a) => `    <xhtml:link rel="alternate" hreflang="${a}" href="${pageUrl(a, file)}"/>`).join("\n")}
    <xhtml:link rel="alternate" hreflang="x-default" href="${BASE}"/>
  </url>`)).join("\n")}
</urlset>
`);

  const basePath = new URL(BASE).pathname;
  write("robots.txt", `User-agent: *\n${LANGS.map((l) => `Disallow: ${basePath}${l}/admin.html`).join("\n")}\n\nSitemap: ${BASE}sitemap.xml\n`);

  // Service worker: precache the shared assets of this version; pages are cached as they are visited.
  const assets = [
    ...listFiles("src").filter((p) => /\.(js|css)$/.test(p) && !/\.stub\.js$|scripts\//.test(p)),
    ...listFiles("assets").filter((p) => !p.includes("photos/")),
  ].map((p) => relative(ROOT, join(ROOT, p)).split("\\").join("/")).sort();
  const hash = createHash("sha256");
  for (const p of assets) hash.update(p).update(read(p));
  for (const b of built) hash.update(read(`${b.lang}/${b.file}`));
  const version = hash.digest("hex").slice(0, 12);
  write("sw.js", read("scripts/sw.template.js").replace("__VERSION__", version).replace("__ASSETS__", JSON.stringify(assets, null, 2)));

  write(".nojekyll", "");
  return { pages: built.length, version };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const r = build();
  console.log(`Built ${r.pages} pages (${LANGS.join(", ")}), service worker version ${r.version}.`);
  if (!existsSync(join(ROOT, "assets/icon.svg"))) console.warn("Warning: assets/icon.svg missing");
}
